    ["Edited"] = "Modificato",
    ["Everyday people"] = "Persone comuni",
    ["Everyday people do not keep memories of your talks."] = "Le persone comuni non conservano ricordi delle tue conversazioni.",
    ["Everything together is too long. Shorten something so it stays under {max} characters."] = "Nel complesso è troppo lungo. Accorcia qualcosa perché resti sotto {max} caratteri.",
    ["Example lines"] = "Battute d’esempio",
    ["Facts the character noticed while you talked. Change or delete the ones that are wrong."] = "Fatti che il personaggio ha notato durante le tue conversazioni. Modifica o elimina quelli sbagliati.",
    ["For example: V has a sister called Lena."] = "Per esempio: V ha una sorella di nome Lena.",
    ["Go back to the shipped text for {name}? All your changes to this character are removed."] = "Tornare al testo originale di {name}? Tutte le tue modifiche a questo personaggio verranno rimosse.",
    ["Go back to the shipped text for {name}? Your changes to this part are removed."] = "Tornare al testo originale di {name}? Le tue modifiche a questa parte verranno rimosse.",
    ["How they sound: pace, attitude, favourite habits of speech."] = "Come suonano: ritmo, atteggiamento, abitudini di linguaggio preferite.",
    ["Lines in their voice. They show the tone only and are never said back word for word."] = "Battute con la loro voce. Mostrano solo il tono e non vengono mai ripetute parola per parola.",
