    ["Save"] = "Salva",
    ["Saved."] = "Salvato.",
    ["Search characters"] = "Cerca personaggi",
    ["Short facts you write yourself, such as a name or a promise. The character knows them in every talk."] = "Brevi fatti che scrivi tu stesso, come un nome o una promessa. Il personaggio li conosce in ogni conversazione.",
    ["Short rules this character always follows when talking, for example: Never swear. Answer in one sentence."] = "Brevi regole che questo personaggio segue sempre quando parla, per esempio: non imprecare mai. Rispondi in una frase.",
    ["Short summary of earlier talks"] = "Breve riepilogo delle conversazioni precedenti",
    ["Speaking rules"] = "Regole di parola",
    ["Speaking style"] = "Stile di parola",
    ["Story characters"] = "Personaggi della storia",
    ["That character was not found."] = "Quel personaggio non è stato trovato.",
    ["The Local AI pack finds these. It is not installed or not ready, so none are collected now."] = "Il pacchetto Local AI le individua. Non è installato o non è pronto, quindi per ora non ne viene raccolta nessuna.",
    ["The bio is too long. Keep it under {max} characters."] = "La biografia è troppo lunga. Mantienila sotto {max} caratteri.",
    ["The bio is too short. Use at least {max} characters."] = "La biografia è troppo corta. Usa almeno {max} caratteri.",
    ["The conversation service is not running, so the editor cannot open. Restart the game."] = "Il servizio di conversazione non è in esecuzione, quindi l’editor non può aprirsi. Riavvia il gioco.",
    ["The editor could not be opened. Try again."] = "Impossibile aprire l’editor. Riprova.",
    ["The editor is closed. You can close this tab."] = "L’editor è chiuso. Puoi chiudere questa scheda.",
    ["World rules"] = "Regole del mondo",
    ["Rules for the whole world, used for every character in every talk: face to face, phone and group chats. Write facts and style, for example how people talk or what nobody knows. They never replace the mod’s own rules."] = "Regole per l’intero mondo, usate per ogni personaggio in ogni conversazione: faccia a faccia, al telefono e nelle chat di gruppo. Scrivi fatti e stile, ad esempio come parla la gente o cosa non sa nessuno. Non sostituiscono mai le regole del mod.",
    ["For example: Nobody in Night City knows V’s name unless V tells them. Everyone speaks casually."] = "Ad esempio: nessuno a Night City conosce il nome di V, a meno che V non lo dica. Tutti parlano in modo informale.",
    ["Applies to every provider: Local AI, Mistral and Custom in the character prompt, and Convai through its dynamic info."] = "Vale per ogni provider: Local AI, Mistral e Custom nel prompt del personaggio, e Convai tramite le sue info dinamiche.",
    ["The world rules are too long. Keep them under {max} characters."] = "Le regole del mondo sono troppo lunghe. Mantienile sotto {max} caratteri.",
    ["Revert changes"] = "Annulla le modifiche",
    ["Clear the world rules?"] = "Svuotare le regole del mondo?",
    ["The example lines are too long together. Keep them under {max} characters in all."] = "Le battute d’esempio sono troppo lunghe nel complesso. Mantienile sotto {max} caratteri in tutto.",
    ["The speaking style is too long. Keep it under {max} characters."] = "Lo stile di parola è troppo lungo. Mantienilo sotto {max} caratteri.",
    ["Things they always know"] = "Cose che sanno sempre",
    ["Too many example lines. Keep {max} or fewer."] = "Troppe battute d’esempio. Ne bastano {max} o meno.",
    ["Too many memories. Keep {max} or fewer."] = "Troppi ricordi. Mantienine {max} o meno.",
    ["Too many rules. Keep {max} or fewer."] = "Troppe regole. Ne bastano {max} o meno.",
    ["Who this character is, what they know and how they look. A long bio makes replies slower, so keep it tight."] = "Chi è questo personaggio, cosa sa e come appare. Una biografia lunga rende le risposte più lente, quindi tienila breve.",
    ["You have changes that are not saved. Leave without saving?"] = "Hai modifiche non salvate. Uscire senza salvare?",
    ["{count} of {max}"] = "{count} di {max}",
    ["Mature content"] = "Contenuti maturi",
    ["Local AI model"] = "Modello Local AI",
    ["Uncensored model"] = "Modello senza censure",
    ["No model installed"] = "Nessun modello installato",
    ["another model"] = "un altro modello",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "Il modello Local AI che hai scelto manca, non entra nella memoria grafica libera o non è stato avviato, quindi al suo posto è stato usato {model}.",
    ["Local AI switched to {model}: the game is using most of your graphics memory."] = "Local AI passata a {model}: il gioco sta usando la maggior parte della memoria video.",
    ["Choose one of the listed Local AI models."] = "Scegli uno dei modelli Local AI elencati.",
    ["Characters to invite"] = "Personaggi da invitare",
    ["Whose memories"] = "Ricordi di chi",
    ["Invalid Mature content settings."] = "Impostazioni dei contenuti maturi non valide.",
    ["Your message was not sent. Open the text box again and retype it."] = "Il tuo messaggio non è stato inviato. Riapri la casella di testo e riscrivilo.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Non utilizzabili: {models}. Vedi le note su Local AI, “Aggiungere un proprio modello”.",
    ["an embedding model, not a chat model"] = "un modello di embedding, non di chat",
    ["could not be read"] = "non leggibile",
    ["file not found"] = "file non trovato",
    ["not a valid GGUF file"] = "non è un file GGUF valido",
    ["{name} (custom)"] = "{name} (personalizzato)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Preparazione di {name}: in attesa che il servizio di conversazione si connetta…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Preparazione di {name}: in attesa che il modello vocale venga caricato…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Preparazione di {name}: in attesa che si apra la connessione di conversazione…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Preparazione di {name}: in attesa che il gioco posizioni il personaggio…",
    ["Preparing {name}: waiting for the memory service…"] = "Preparazione di {name}: in attesa del servizio di memoria…",
    ["Preparing {count} more companions…"] = "Preparazione di altri {count} compagni…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "Il servizio di conversazione non ha risposto. Attendi un momento, poi invita di nuovo.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "Il modello vocale non è stato caricato. Controlla la voce in Impostazioni o scegline un'altra, poi invita di nuovo.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Il servizio di memoria non ha risposto. Controlla la connessione, poi invita di nuovo.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "La connessione di conversazione non si è aperta. Controlla la connessione, poi invita di nuovo.",
    ["Calls are not available during combat."] = "Le chiamate non sono disponibili durante il combattimento.",
    ["Calls are not available right now."] = "Le chiamate non sono disponibili al momento.",
    ["Holocall ended: combat started."] = "Holochiamata terminata: è iniziato il combattimento.",
    ["Holocall with {name} ended."] = "Holochiamata con {name} terminata.",
    ["Live picture unavailable. The call continues with the portrait."] = "Immagine dal vivo non disponibile. La chiamata prosegue con il ritratto.",
    ["This contact cannot take a holocall."] = "Questo contatto non può ricevere una holochiamata.",
    ["You are already on a call."] = "Sei già in una chiamata.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "Un compagno vicino fa un breve commento all’inizio del combattimento e un altro dopo.\n\nDieci minuti di pausa dopo uno scontro. Conversazioni e scene della storia hanno la precedenza. Caricare un salvataggio azzera la pausa.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Chiedi a un compagno di guidare fino al punto sulla mappa che hai selezionato.\n\nSali sul sedile del passeggero quando è pronto.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Auto: segue l’incontro concluso in questo salvataggio.\n\nOccasionale: parla con questa familiarità.\n\nOrdinario: mantiene il suo modo abituale.\n\nNon implica una relazione in corso.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Auto: segue la relazione in questo salvataggio.\n\nRomantico: parla con V come con un partner.\n\nOrdinario: mantiene il loro modo abituale.\n\nCambia solo il modo di parlare, mai le scelte di gioco.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "L’audio Bluetooth arriva con un leggero ritardo, quindi labbra e sottotitoli possono precedere la voce. Questa opzione li trattiene per allinearli, per ogni voce.\n\nAuto: 150 ms mentre Windows riproduce tramite Bluetooth, nessun ritardo altrimenti. Scegli un valore se le tue cuffie sono più veloci o più lente.\n\nIl dialogo del gioco ha lo stesso ritardo e non lo corregge.",
    ["Characters sometimes ask about something you said, pick up something from earlier or share a thought that invites an answer.\n\nNow and then, never on every reply, and never while you are leaving, giving an order or fighting."] = "I personaggi a volte chiedono di qualcosa che hai detto, riprendono qualcosa di prima o condividono un pensiero che invita a rispondere.\n\nOgni tanto, mai a ogni risposta, e mai mentre ti allontani, dai un ordine o combatti.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "La cronologia delle chat resta disponibile tra un avvio del gioco e l’altro.\n\nFar dimenticare un personaggio cancella anche i suoi messaggi Chat e le bozze salvati. Dimenticare tutti i ricordi cancella tutte le chat salvate.",
    ["Cinematic: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nThe Subtitles switch turns both off."] = "Cinematografici: i normali sottotitoli dei dialoghi del gioco.\n\nSopra chi parla: sopra il compagno che sta parlando.\n\nL’interruttore Sottotitoli li disattiva entrambi.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "I compagni commentano dopo che hai finito di raccogliere il bottino nel mondo. I trasferimenti nel deposito restano silenziosi.\n\nI commenti normali distano dieci minuti l’uno dall’altro; l’equipaggiamento leggendario appena ottenuto ha una pausa propria di due minuti.\n\nGli oggetti raccolti durante un combattimento vengono riuniti in un unico commento alla fine.",
    ["Copy your free key from Mistral first (signing up there needs phone verification). It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder. Mistral allows about one message a second and about 5,000 turns a day. It sets its own monthly cap, estimated at about 150,000 turns."] = "Copia prima la tua chiave gratuita da Mistral (per registrarsi serve la verifica del telefono). Viene letta dagli appunti una sola volta, verificata con Mistral e salvata su questo computer.\n\nPuoi anche salvarla in player-mistral-key.txt nella cartella del servizio di conversazione. Mistral consente circa un messaggio al secondo e circa 5.000 turni al giorno. Il limite mensile lo imposta Mistral stesso, stimato in circa 150.000 turni.",
    ["Custom models are ones you added; they join the default choice by size."] = "I modelli aggiunti da te entrano nella scelta predefinita per dimensione.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Solo occhi: la testa resta ferma e si muovono solo gli occhi.\n\nSottile fino a Intenso: la testa si gira sempre più verso di te.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups (joining steps, dismissals, driving instructions, results of companion actions), writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nPreparation progress, joined notices, failures and replies to Stop trip stay visible when it is off."] = "Per test e segnalazioni di bug; lascia disattivato per il gioco normale.\n\nMostra i popup di routine (passaggi di adesione, congedi, istruzioni di guida, esiti delle azioni dei compagni), scrive una traccia dei movimenti nella cartella di runtime del mod, registra le decisioni sui gesti e si aggiunge ai report di supporto.\n\nL’avanzamento della preparazione, gli avvisi di adesione, gli errori e le risposte a «Ferma tragitto» restano visibili anche quando è disattivato.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "Dimentica tutti i ricordi si applica a questi personaggi.\n\nSfogliare il catalogo o invitare un compagno non aggiunge nessuno a questo conteggio.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "Membri di gang, agenti NCPD, guardie, ripperdoc, negozianti, barman e passanti rispondono come il loro tipo di persona.\n\nNon conoscono la tua storia e ti dimenticano dopo il caricamento di un salvataggio, tranne i negozianti da cui torni.\n\nI personaggi con nome non sono interessati.",
    ["Talk to story characters"] = "Parla con i personaggi della storia",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand. They use their own voice and memory, and their face follows what they say.\n\nNothing else about them changes: they do not turn, move, gesture or follow. They do not answer during scenes, quest conversations, fights or rides.\n\nTakes effect after you reload your save."] = "I personaggi del gioco con un nome, come Judy, Jackie, Panam e Rogue, rispondono quando parli con loro dove si trovano. Usano la propria voce e memoria, e il loro viso segue ciò che dicono.\n\nNient’altro in loro cambia: non si voltano, non si muovono, non gesticolano né ti seguono. Non rispondono durante scene, dialoghi di missione, combattimenti o corse in auto.\n\nDiventa effettivo dopo aver ricaricato il salvataggio.",
    ["{name} is busy right now."] = "{name} non è disponibile in questo momento.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Se un personaggio smette di rispondere, le voci si fermano o compare un errore: scegli Genera report e invia il file indicato allo sviluppatore, con una breve nota su cosa stavi facendo.\n\nI log elencati sotto mostrano cosa è andato storto.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "I personaggi invitati vengono preparati subito. I loro ricordi iniziano quando gli parli davvero.\n\nUn’unica identità giocatore è condivisa tra tutti i salvataggi e resta la stessa dopo aver dimenticato.\n\nIl contesto di gioco attuale descrive il mondo che hai caricato.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Trovati solo modelli per adulti. Attiva i Contenuti maturi.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Mai consentito: sesso con minori o senza consenso, sesso con persone reali, odio, istruzioni reali su armi o droghe. Un controllo di sicurezza applica la regola sui minori.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Disattivato: le risposte sono solo testo e non viene generata alcuna voce.\n\nCon anche i Sottotitoli disattivati, le reazioni automatiche restano silenziose.",
    ["Pocket: the lightest, runs on your CPU, starts speaking in about 0.2 s.\n\nOmniVoice: richer, especially on harder voices. Needs a capable GPU and the OmniVoice pack (greyed out until it is installed); the higher tiers start in 1 to 2.5 s.\n\nVoxtral: each companion’s own voice from the cloud, with your own Mistral key, in English and many other languages. It loads no local voice model.\n\nConvai: its own cloud voice. A voice that cannot run is replaced by a simpler one, with one notice."] = "Pocket: la più leggera, gira sulla CPU e inizia a parlare in circa 0,2 s.\n\nOmniVoice: più ricca, soprattutto con le voci più difficili. Richiede una GPU capace e il pacchetto OmniVoice (disattivato finché non è installato); i livelli superiori partono in 1-2,5 s.\n\nVoxtral: la voce di ogni compagno dal cloud, con la tua chiave Mistral, in inglese e in molte altre lingue. Non carica alcun modello vocale locale.\n\nConvai: la sua voce cloud. Una voce che non può funzionare viene sostituita con una più semplice, con un solo avviso.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Vedi cosa ricorda ciascun personaggio e fai dimenticare a uno o a tutti.\n\nI ricordi vengono conservati tra un salvataggio e l’altro.",
    ["Shows companion replies as text.\n\nWith Voice playback off as well, automatic reactions stay silent."] = "Mostra le risposte dei compagni come testo.\n\nCon anche Riproduzione vocale disattivata, le reazioni automatiche restano silenziose.",
    ["Voxtral · not with Mature"] = "Voxtral · non con 18+",
    ["Voxtral is not used with Mature content."] = "Voxtral non viene usato con i Contenuti maturi.",
    ["Needs Local AI or Custom."] = "Richiede Local AI o Custom.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "Linguaggio forte, violenza esplicita, droghe e, tra adulti consenzienti, flirt e sesso. Solo adulti (18+). Richiede Local AI o Custom.",
    ["From Convai or Mistral, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Da Convai o Mistral, attivandolo seleziona Local AI, oppure Personalizzato se Local AI non è installata. Con Local AI seleziona anche il modello senza censure più grande che entra. Disattivandolo si ripristinano le tue scelte.",
    ["Choosing Convai or Mistral turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Scegliere Convai o Mistral disattiva questa opzione. Voxtral non viene usato con essa: una voce su Voxtral passa a Pocket e torna quando l’opzione viene disattivata.",
    ["Use it if companions seem to look above or below your eyes."] = "Usalo se i compagni sembrano guardare sopra o sotto i tuoi occhi.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Cloud Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · serve chiave Mistral",
    ["{name} (custom · too large)"] = "{name} (personale · troppo grande)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (personale, {size} GB, richiede {need} GB)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (personale, {size} GB, troppo grande per questa scheda)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Cancella i ricordi su di te presso tutti i personaggi con cui hai parlato.\n\nLa tua identità di giocatore resta. Prima una conferma.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Salva un file di report da inviare allo sviluppatore.\n\nChiavi API, token, ID, audio del microfono e testo delle conversazioni non sono inclusi. Senza il servizio di conversazione viene creato un report più breve con i file che il gioco può leggere.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "Modelli senza censure (per Local AI) del Mature pack: effetto pieno. Gli standard rifiutano quasi sempre il sesso. Pack: installato.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Modelli senza censure (per Local AI) del Mature pack: effetto pieno. Gli standard rifiutano quasi sempre il sesso. Pack: non installato (facoltativo, pagina Hugging Face del mod).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Finché non scegli, Local AI carica il modello più grande che entra nella memoria grafica libera.\n\nUn modello alla volta; le modifiche valgono al caricamento successivo. Modello mancante, troppo grande o in errore: sostituito dal più grande che entra, con un avviso.",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai non ha accettato la tua chiave API. Controllala in Impostazioni > Fornitore di conversazione.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Impossibile avviare Local AI. Controlla Local AI in Impostazioni > Fornitore di conversazione.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral non ha accettato la tua chiave. Controllala in Impostazioni > Fornitore di conversazione.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Mistral non ha ancora una chiave, quindi viene usato Convai. Aggiungi la tua chiave in Impostazioni > Fornitore di conversazione.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Richiede una chiave API di Mistral (aggiungila in Impostazioni > Fornitore di conversazione)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Parlare con i compagni richiede Convai per ora. Imposta Fornitore di conversazione su Convai (piano gratuito) in Impostazioni > Fornitore di conversazione, oppure scrivi il tuo messaggio.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider."] = "È stato raggiunto il limite di conversazioni. Riprova più tardi oppure aggiungi una chiave API gratuita di Mistral e imposta Fornitore di conversazione su Mistral in Impostazioni > Fornitore di conversazione.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "La tua chiave API di Convai ha raggiunto il limite del piano. Riprova più tardi o aggiungi un'altra chiave in Impostazioni > Fornitore di conversazione.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Mistral (free, with your own free key) allows about 5,000 turns a day. Local AI is unlimited and runs on your PC."] = "Hai raggiunto il limite giornaliero di Convai (piano gratuito). Si azzera domani. Per continuare subito, scegli un altro fornitore in Impostazioni > Fornitore di conversazione. Mistral (gratuito, con una tua chiave gratuita) consente circa 5.000 turni al giorno. Local AI è illimitata e funziona sul tuo PC.",
    ["Today’s {limit} Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Oggi {limit} turni Convai usati.\nUsa Mistral (chiave gratis, ~5.000/giorno) o Local AI (illimitata).",
    ["Today’s Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Turni Convai di oggi esauriti.\nUsa Mistral (chiave gratis, ~5.000/giorno) o Local AI (illimitata).",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral, Local AI or Custom as the conversation provider in the settings."] = "Convai sta rispondendo in questo momento, quindi queste modifiche non hanno ancora effetto. Scegli Mistral, Local AI o Personalizzato come fornitore di conversazione nelle impostazioni.",
    ["Your changes work with Mistral, Local AI and Custom. They do not apply to Convai."] = "Le tue modifiche funzionano con Mistral, Local AI e Personalizzato. Non si applicano a Convai.",
    ["Paste"] = "Incolla",
    ["no Omni pack"] = "senza pacchetto Omni",
    ["Add your Convai API key below to see and buy a plan."] = "Aggiungi la tua chiave API di Convai qui sotto per vedere i piani e acquistarne uno.",
    ["Add your Convai API key first."] = "Aggiungi prima la tua chiave API di Convai.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Aggiungi prima la tua chiave API di Convai: copiala, poi scegli Incolla nella riga Chiave API di Convai.",
    ["Asking Convai for the payment page…"] = "Richiesta della pagina di pagamento a Convai…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Chiede a Convai quale piano ha ora la tua chiave. Dopo il pagamento possono volerci circa 15 secondi.",
    ["Billed every month."] = "Addebito mensile.",
    ["Billed once a year."] = "Addebito annuale.",
    ["Buy"] = "Acquista",
    ["Check"] = "Controlla",
    ["Check my plan"] = "Controlla il mio piano",
    ["Checking your plan…"] = "Controllo del tuo piano…",
    ["Choose Check my plan to ask Convai."] = "Scegli Controlla il mio piano per chiedere a Convai.",
    ["Contacting Convai…"] = "Contatto con Convai…",
    ["Convai could not start the payment. Try again later."] = "Convai non è riuscito ad avviare il pagamento. Riprova più tardi.",
    ["Convai did not accept your API key."] = "Convai non ha accettato la tua chiave API.",
    ["Convai does not show a paid plan for your key yet."] = "Convai non mostra ancora un piano a pagamento per la tua chiave.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "Convai non ha ancora confermato il tuo piano. Controllalo in Impostazioni > Piano a pagamento di Convai.",
    ["Convai paid tier"] = "Piano a pagamento di Convai",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "La pagina di pagamento di Convai è aperta nel tuo browser. Il tuo piano è attivo circa 15 secondi dopo il pagamento.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "Il servizio di pagamento di Convai non ha risposto. Riprova tra poco.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Piani di Convai per questo mod: più conversazioni di Convai con la tua chiave API di Convai. Apre una pagina con i piani e i relativi prezzi.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Le conversazioni con la chiave API di Convai scelta come fornitore usano questo piano.",
    ["Get your Convai API key"] = "Ottieni la tua chiave API di Convai",
    ["Manage or cancel plan"] = "Gestisci o annulla piano",
    ["Free"] = "Gratuito",
    ["Gamer, monthly"] = "Gamer, mensile",
    ["Gamer, yearly"] = "Gamer, annuale",
    ["Gamer Pro, monthly"] = "Gamer Pro, mensile",
    ["Gamer Pro, yearly"] = "Gamer Pro, annuale",
    ["Current plan"] = "Piano attuale",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Questo è il tuo piano attuale. Per cambiarlo o annullarlo, scegli Gestisci o annulla piano qui sotto.",
    ["No key added"] = "Nessuna chiave aggiunta",
    ["Not checked yet"] = "Non ancora controllato",
    ["Opened in your browser."] = "Aperto nel tuo browser.",
    ["Opening the page in your browser…"] = "Apertura della pagina nel tuo browser…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Apre la pagina di pagamento di Convai (Stripe) nel tuo browser. Paghi direttamente Convai; il mod non vede mai la tua carta. Il tuo piano è attivo circa 15 secondi dopo il pagamento, e le conversazioni usano poi la tua chiave API di Convai.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Apre convai.com nel tuo browser. Accedi o crea un account gratuito, copia la tua chiave API, poi torna qui e scegli Incolla qui sotto.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Apre la tua pagina di fatturazione di Convai nel tuo browser. Accedi con lo stesso account Convai per cambiare o annullare il tuo piano.",
    ["Plans"] = "Piani",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Piani creati da Convai per questo mod. Danno più conversazioni alla tua chiave API di Convai; il piano gratuito resta com'è.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Prezzi in dollari statunitensi. Puoi annullare in qualsiasi momento dalla pagina di fatturazione di Convai.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "Il servizio di conversazione non è in esecuzione, quindi i piani non possono essere mostrati. Riavvia il gioco.",
    ["This key has no paid plan. Choose a plan below."] = "Questa chiave non ha un piano a pagamento. Scegli un piano qui sotto.",
    ["Your Convai plan"] = "Il tuo piano Convai",
    ["Your Convai plan is active."] = "Il tuo piano Convai è attivo.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Il tuo piano Convai è attivo. Scegli Chiave API di Convai in Impostazioni > Fornitore di conversazione.",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Il tuo piano Convai è attivo. Le conversazioni ora usano la tua chiave API di Convai.",
    ["Your browser could not be opened."] = "Impossibile aprire il browser.",
    ["Your plan could not be read right now. Try again in a moment."] = "Impossibile leggere il tuo piano in questo momento. Riprova tra poco.",
    ["{count} Convai interactions a month."] = "{count} interazioni Convai al mese.",
    ["{plan}, {price} a month"] = "{plan}, {price} al mese",
    ["{plan}, {price} a year"] = "{plan}, {price} all'anno",
    ["Sign in with Convai"] = "Accedi con Convai",
    ["Sign in"] = "Accedi",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Apre la pagina di accesso di Convai nel tuo browser.\n\nAccedi o crea un account gratuito: la tua chiave API di Convai viene salvata su questo computer, come con Incolla. Hai cinque minuti.",
    ["Opening Convai’s sign-in page in your browser…"] = "Apertura della pagina di accesso di Convai nel tuo browser…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Accedi alla pagina di Convai nel tuo browser. La tua chiave verrà salvata qui al termine.",
    ["Signed in. Your Convai API key is saved."] = "Accesso eseguito. La tua chiave API di Convai è salvata.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "L'accesso ha impiegato troppo tempo. Scegli Accedi con Convai per riprovare.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "L'accesso non è stato completato. Riprova, oppure copia la tua chiave da convai.com e scegli Incolla.",
    ["Choose one of the listed voices for V."] = "Scegli una delle voci elencate per V.",
    ["Pocket · On your PC"] = "Pocket · Sul tuo PC",
    ["Johnny in your head"] = "Johnny nella tua testa",
    ["Choose how often Johnny speaks up."] = "Scegli ogni quanto interviene Johnny.",
    ["A display name is too long. Keep each one under {max} characters."] = "Un nome visualizzato è troppo lungo. Tienine ciascuno sotto {max} caratteri.",
    ["A clip you add replaces the shipped voice of this character for Pocket, OmniVoice and the Voxtral cloud voice."] = "Un clip che aggiungi sostituisce la voce originale di questo personaggio per Pocket, OmniVoice e la voce cloud Voxtral.",
    ["A new or removed clip counts from the next line this character speaks, once the current reply is over. Nothing needs restarting."] = "Una clip nuova o rimossa vale dalla prossima battuta di questo personaggio, quando la risposta in corso è finita. Non serve riavviare nulla.",
    ["A record name can only use letters, digits, dots, dashes and underscores, for example Character.Rebecca."] = "Un nome di record può usare solo lettere, cifre, punti, trattini e trattini bassi, per esempio Character.Rebecca.",
    ["Add a display name"] = "Aggiungi un nome visualizzato",
    ["Add a record name"] = "Aggiungi un nome di record",
    ["Add a record name or a display name, so the game can find this character."] = "Aggiungi un nome di record o un nome visualizzato, così il gioco può trovare questo personaggio.",
    ["Add voice clip"] = "Aggiungi clip vocale",
    ["Another character of yours, {other}, already answers to this record or name."] = "Un altro tuo personaggio, {other}, risponde già a questo record o nome.",
    ["Choose a gender"] = "Scegli un genere",
    ["Choose a gender."] = "Scegli un genere.",
    ["Chosen file: {name} ({size}). It is checked when you save it."] = "File scelto: {name} ({size}). Viene controllato quando lo salvi.",
    ["Chosen file: {name}, {seconds} seconds."] = "File scelto: {name}, {seconds} secondi.",
    ["Clip removed."] = "Clip rimosso.",
    ["Delete character"] = "Elimina personaggio",
    ["Delete {name}? The character, its voice clip and what it remembers of you are removed."] = "Eliminare {name}? Verranno rimossi il personaggio, il suo clip vocale e ciò che ricorda di te.",
    ["Display names"] = "Nomi visualizzati",
    ["Edit a character’s bio, speaking style, speaking rules and memories, or make a character of your own, in your browser.\n\nWorks with Mistral, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Modifica nel tuo browser la biografia, lo stile di parola, le regole di parola e i ricordi di un personaggio, oppure crea un personaggio tuo.\n\nFunziona con Mistral, Local AI e Personalizzato, non con Convai. Le modifiche si applicano dalla prossima risposta.",
    ["Female"] = "Femminile",
    ["Filled in from the character you were facing: {name}."] = "Compilato con il personaggio che stavi guardando: {name}.",
    ["For example: Character.Rebecca"] = "Per esempio: Character.Rebecca",
    ["For example: Rebecca"] = "Per esempio: Rebecca",
    ["Gender"] = "Genere",
    ["Give the character a name."] = "Dai un nome al personaggio.",
    ["How the game finds this character"] = "Come il gioco trova questo personaggio",
    ["It picks the voice when the character has no clip."] = "Se il personaggio non ha un clip, la voce la sceglie il genere.",
    ["Male"] = "Maschile",
    ["Memories"] = "Ricordi",
    ["Name"] = "Nome",
    ["New character"] = "Nuovo personaggio",
    ["No clip yet."] = "Nessun clip per ora.",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "Facoltativo. Pocket, OmniVoice e la voce cloud Voxtral copiano un clip che aggiungi. Senza clip il personaggio parla con una voce generica adatta al genere.",
    ["Play saved clip"] = "Riproduci clip salvato",
    ["Record names"] = "Nomi di record",
    ["Remove clip"] = "Rimuovi clip",
    ["Remove the voice clip? The character goes back to a generic voice."] = "Rimuovere il clip vocale? Il personaggio torna a una voce generica.",
    ["Remove the voice clip? {name} goes back to the shipped voice."] = "Rimuovere il clip vocale? {name} torna alla voce originale.",
    ["Save clip"] = "Salva clip",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "Salva prima il personaggio. Poi potrà avere un clip vocale e comincerà a ricordare le tue conversazioni.",
    ["Saved clip: {seconds} seconds."] = "Clip salvato: {seconds} secondi.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "Salvato. Il clip è un po’ lungo: da 10 a 18 secondi è la durata che si copia meglio.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "Salvato. Il clip è un po’ corto: da 10 a 18 secondi è la durata che si copia meglio.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "Quel file non è una registrazione che le voci possono leggere. Usa un file WAV, MP3, OGG o FLAC.",
    ["That file is too big for a voice clip."] = "Quel file è troppo grande per un clip vocale.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "Il clip è quasi tutto silenzio. Usa un clip in cui qualcuno parla per la maggior parte del tempo.",
    ["The clip is too long. Use at most {max} seconds."] = "Il clip è troppo lungo. Usa al massimo {max} secondi.",
    ["The clip is too short. Use at least {min} seconds."] = "Il clip è troppo corto. Usa almeno {min} secondi.",
    ["The game did not name anyone. Face the character, then choose Settings > Edit characters > Open in the game again."] = "Il gioco non ha nominato nessuno. Guarda il personaggio, poi scegli di nuovo Impostazioni > Modifica personaggi > Apri nel gioco.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "Il gioco riconosce la persona con cui parli tramite un nome di record, un nome visualizzato o entrambi. Un nome di record ha questa forma: Character.Rebecca o NCA.Rebecca. Aggiungine almeno uno.",
    ["The name is too long. Keep it under {max} characters."] = "Il nome è troppo lungo. Tienilo sotto {max} caratteri.",
    ["The name of the character’s record in the game files."] = "Il nome del record del personaggio nei file del gioco.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "Il nome con cui si presenta il personaggio. Lo dice quando qualcuno gli chiede chi è.",
    ["The name the game shows for the character."] = "Il nome che il gioco mostra per il personaggio.",
    ["The recording is distorted. Record it again, a little quieter."] = "La registrazione è distorta. Registrala di nuovo, un po’ più piano.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "La qualità della registrazione è troppo bassa. Usa almeno {min} Hz.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "La registrazione è troppo bassa per essere copiata. Registra più forte o più vicino al microfono.",
    ["The saved clip could not be loaded."] = "Il clip salvato non può essere caricato.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "Le parole dette nel clip sono troppo lunghe. Tienile sotto {max} caratteri.",
    ["This character speaks with a generic voice that fits the gender."] = "Questo personaggio parla con una voce generica adatta al genere.",
    ["This character speaks with the shipped voice."] = "Questo personaggio parla con la voce originale.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "Questo computer non può convertire quel file. Salvalo come WAV e riprova.",
    ["Too many display names. Keep {max} or fewer."] = "Troppi nomi visualizzati. Tienine {max} o meno.",
    ["Too many record names. Keep {max} or fewer."] = "Troppi nomi di record. Tienine {max} o meno.",
    ["Type the words said in the clip, at least {min} characters."] = "Scrivi le parole dette nel clip, almeno {min} caratteri.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "Scrivi ciò che dice il clip, come viene pronunciato. OmniVoice ne ha bisogno per copiare la voce.",
    ["Use the character I’m facing"] = "Usa il personaggio che sto guardando",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "Usa da {min} a {max} secondi di una sola persona che parla chiaramente, senza musica né altre voci. Da {goodMin} a {goodMax} secondi è la durata che si copia meglio. WAV, MP3, OGG o FLAC.",
    ["Voice"] = "Voce",
    ["You have as many voice clips as the editor keeps ({max}). Remove one first."] = "Hai tanti clip vocali quanti ne tiene l’editor ({max}). Rimuovine prima uno.",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "Chi è questo personaggio, che cosa sa e che aspetto ha. Scriverlo come «Io sono …» funziona meglio. Una biografia lunga rende le risposte più lente, quindi tienila breve.",
    ["Words said in the clip"] = "Parole dette nel clip",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "Hai creato tutti i personaggi che l’editor può contenere ({max}). Elimina prima uno.",
    ["Your character"] = "Il tuo personaggio",
    ["Your characters"] = "I tuoi personaggi",
    ["Your own characters talk only with Mistral, Local AI or Custom. With Convai they speak as an ordinary person."] = "I tuoi personaggi parlano solo con Mistral, IA locale o Personalizzato. Con Convai parlano come una persona normale.",
    ["{name} is one of your own characters. They need Mistral, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} è uno dei tuoi personaggi. Ha bisogno di Mistral, IA locale o Personalizzato, quindi con Convai parla come una persona normale.",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "{other} ha già un profilo nel mod, e quel profilo prevale sempre. Usa un altro record o nome.",
    ["A pack is one folder too deep. See Help in Settings."] = "Pack con una cartella in più. Vedi Aiuto in Impostazioni.",
    ["All files found."] = "Tutti i file trovati.",
    ["Browser"] = "Browser",
    ["Found."] = "Trovato.",
    ["Found: {list}."] = "Trovati: {list}.",
    ["Game version"] = "Versione del gioco",
    ["Graphics card"] = "Scheda grafica",
    ["Internet"] = "Internet",
    ["Loaded."] = "Caricato.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "L'IA locale non è partita. Genera un report qui sotto e invialo, oppure scegli un altro fornitore di conversazione.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "L'IA locale non ha trovato una scheda grafica utilizzabile. Serve una scheda NVIDIA o AMD con driver aggiornato. Aggiorna il driver oppure scegli un altro fornitore di conversazione.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Mancanti: {files}. Estrai di nuovo lo zip Scripts nella cartella di Cyberpunk 2077 e lascia che sostituisca i file.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. I file creati dalla mod vanno nella sua cartella Overwrite; lasciali lì. Cita Mod Organizer 2 quando invii un report.",
    ["Mod files"] = "File della mod",
    ["Mod manager"] = "Gestore di mod",
    ["Moved into place from {folder}: {packs}."] = "Spostati da {folder}: {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Nessun pack di IA locale trovato. Scaricane uno dalla pagina Hugging Face della mod ed estrailo nella cartella di Cyberpunk 2077, oppure scegli un altro fornitore di conversazione.",
    ["No problem found. Select a line to see what was checked."] = "Nessun problema trovato. Seleziona una riga per vedere cosa è stato controllato.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the Runtime zip straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The Runtime is a separate download from the mod’s Hugging Face page; the Nexus page links to it."] = "Nessuna traccia del servizio di conversazione in questa sessione: Runtime mancante o non caricato. Estrai lo zip del Runtime direttamente nella cartella di Cyberpunk 2077 (non in una nuova cartella), controlla che ci sia red4ext/plugins/AiNpcCyberpunkMod, poi riavvia il gioco. Il Runtime è un download separato dalla pagina Hugging Face della mod; la pagina Nexus rimanda a essa.",
    ["None found: installed by hand."] = "Nessuno trovato: installato a mano.",
    ["None installed. They are optional."] = "Nessuno installato. Sono facoltativi.",
    ["Not needed: Local AI and the voice run on this PC."] = "Non necessario: l'IA locale e la voce girano su questo PC.",
    ["Not used"] = "Non usato",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Non è il tuo fornitore di conversazione. Sceglilo in Impostazioni > Fornitore di conversazione.",
    ["Note"] = "Nota",
    ["OK"] = "OK",
    ["Optional packs"] = "Pack facoltativi",
    ["Problem"] = "Problema",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Problemi trovati: {count}. Seleziona una riga contrassegnata come Problema per leggere cosa fare.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "RED4ext non è caricato. Installalo da Nexus Mods e riavvia il gioco. Avvia anche il servizio di conversazione.",
    ["Reached {host}."] = "Raggiunto {host}.",
    ["Scripts and Runtime"] = "Scripts e Runtime",
    ["Scripts {scripts} and Runtime {runtime} do not match. Download both for the same version and extract them into the Cyberpunk 2077 folder."] = "Scripts {scripts} e Runtime {runtime} non corrispondono. Scaricali entrambi della stessa versione ed estraili nella cartella di Cyberpunk 2077.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Download the Runtime for the same version and extract it into the Cyberpunk 2077 folder, then restart the game."] = "Il servizio di conversazione non ha risposto al controllo installazione, quindi il suo Runtime è probabilmente più vecchio di questi Scripts. Scarica il Runtime della stessa versione, estrailo nella cartella di Cyberpunk 2077 e riavvia il gioco.",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} e Runtime {runtime}.",
    ["Setup check"] = "Controllo installazione",
    ["Some mod files are missing. Extract the Scripts zip again. See Help in Settings."] = "Mancano file della mod. Estrai di nuovo lo zip Scripts. Vedi Aiuto in Impostazioni.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Alcuni file del pack non sono stati spostati perché ci sono già file diversi. Estrai di nuovo il pack nella cartella di Cyberpunk 2077 e lascia che sostituisca i file.",
    ["The Runtime is incomplete ({code}). Download it again and extract it into the Cyberpunk 2077 folder (or apply the Runtime update zips in order), then restart the game."] = "Il Runtime è incompleto ({code}). Scaricalo di nuovo, estrailo nella cartella di Cyberpunk 2077 (oppure applica gli zip di aggiornamento del Runtime in ordine), poi riavvia il gioco.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the Runtime zip straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "Il file delle impostazioni del launcher, launcher.ini, manca in red4ext/plugins/AiNpcCyberpunkMod, quindi il gioco non può avviare il servizio di conversazione. Estrai di nuovo lo zip del Runtime direttamente nella cartella di Cyberpunk 2077 (a mano, anche con Vortex) sostituendo i file, poi riavvia il gioco.",
    ["The Scripts and Runtime versions do not match. Install the same version of both."] = "Versioni di Scripts e Runtime diverse. Installa la stessa versione di entrambi.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "Il servizio di conversazione non raggiunge Internet. Vedi Aiuto in Impostazioni.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "Il servizio di conversazione non raggiunge {host}. Consenti Node.js nel firewall o antivirus (Windows lo chiede una volta; scegli Consenti accesso), controlla la connessione Internet, poi riavvia il gioco.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "Il servizio di conversazione non è riuscito ad avviarsi ({code}). Riavvia il gioco. Se succede di nuovo, genera un report qui sotto e invialo.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "Il servizio di conversazione non è partito. Runtime installato? Vedi Aiuto in Impostazioni.",
    ["The game version could not be read."] = "Impossibile leggere la versione del gioco.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Questo PC non riesce a risolvere {host}. Controlla la connessione Internet, poi riavvia il gioco.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Apri r6/logs/redscript_rCURRENT.log. Una mod citata lì blocca il caricamento degli script.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware, Audioware or redscript, or a game version other than 2.31, can also cause it."] = "Gli script di questa mod non sono stati caricati. Apri r6/logs/redscript_rCURRENT.log. Se l'errore nomina un'altra mod, il problema è quella mod. Possono causarlo anche Codeware, Audioware o redscript mancanti o vecchi, oppure una versione del gioco diversa da 2.31.",
    ["Missing: {names}. Install them and restart the game."] = "Mancano: {names}. Installali e riavvia il gioco.",
    ["Install or update: {names}. Then restart the game."] = "Installa o aggiorna: {names}. Poi riavvia il gioco.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "Codeware è troppo vecchio. Aggiornalo da Nexus Mods e riavvia il gioco.",
    ["Audioware {version} is installed, but this mod’s scripts were built without it. Update Audioware to 1.9.9 or newer from Nexus Mods, then restart the game. If it is already up to date, generate a report below and send it."] = "Audioware {version} è installato, ma gli script di questa mod sono stati compilati senza di esso. Aggiorna Audioware alla 1.9.9 o successiva da Nexus Mods, poi riavvia il gioco. Se è già aggiornato, genera un report qui sotto e invialo.",
    ["Audioware is missing. Install Audioware 1.9.9 or newer from Nexus Mods (nexusmods.com/cyberpunk2077/mods/12001), extract it into the Cyberpunk 2077 folder, then restart the game."] = "Audioware è assente. Installa Audioware 1.9.9 o successiva da Nexus Mods (nexusmods.com/cyberpunk2077/mods/12001), estrailo nella cartella di Cyberpunk 2077, poi riavvia il gioco.",
    ["Audioware is installed but unused. Update it to 1.9.9 or newer, then restart the game."] = "Audioware è installato ma non usato. Aggiornalo alla 1.9.9 o successiva e riavvia il gioco.",
    ["Version {version}."] = "Versione {version}.",
    ["Version {version}. The mod is tested on 2.31 only, so some things may not work."] = "Versione {version}. La mod è testata solo sulla 2.31, quindi alcune cose potrebbero non funzionare.",
    ["Vortex. Install the Runtime and the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say."] = "Vortex. Installa a mano il Runtime e i pack facoltativi nella cartella di Cyberpunk 2077, come indicano i passaggi di installazione.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "Manca {name}. Installalo da Nexus Mods e riavvia il gioco.",
    ["{name}, {memory} GB of video memory."] = "{name}, {memory} GB di memoria video.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} ha una cartella di troppo, in {folder}. Riavvia il gioco e il mod lo sposta al posto giusto. Se è ancora lì dopo, sposta la cartella red4ext che c'è dentro nella cartella di Cyberpunk 2077.",
    ["Add an endpoint URL and a model ID first."] = "Aggiungi prima l’URL dell’endpoint e l’ID del modello.",
    ["Convai: the custom provider is not set up yet"] = "Convai: provider personalizzato non ancora configurato",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Copia l’URL di base dal tuo provider, per esempio https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 oppure http://localhost:11434/v1 (Ollama). Viene letta dagli appunti una sola volta e salvata solo su questo computer.\n\nSolo questo computer e la tua rete domestica possono usare http://. Puoi anche compilare endpoint=, model= e api-key= in player-custom-endpoint.txt nella cartella del servizio di conversazione.\n\nNulla viene inviato finché non scegli questo provider o non premi Prova connessione.",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Copia prima l’ID del modello dal tuo provider, per esempio meta-llama/llama-3.1-8b-instruct su OpenRouter o llama3.2 su Ollama. Viene letto dagli appunti una sola volta e salvato solo su questo computer.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Copia prima la tua chiave API dal provider. Viene letta dagli appunti una sola volta e salvata solo su questo computer. Un server sul tuo computer, come Ollama o LM Studio, di solito non richiede una chiave.",
    ["Custom (OpenAI-compatible)"] = "Personalizzato (API OpenAI)",
    ["Custom API key"] = "Chiave API personale",
    ["Custom endpoint URL"] = "URL dell’endpoint personale",
    ["Custom model ID"] = "ID modello personale",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Risposte del provider personalizzato: voce locale, non la voce cloud di Convai.",
    ["Custom: key not accepted"] = "Personalizzato: chiave non accettata",
    ["Custom: model unavailable"] = "Personalizzato: modello non disponibile",
    ["Custom: out of credits"] = "Personalizzato: crediti esauriti",
    ["Custom: rate limited for now"] = "Personalizzato: limitato per ora",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Elimina l’URL endpoint salvato. Il provider personalizzato ne ha bisogno per rispondere.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Elimina la chiave salvata. Le risposte del provider personalizzato vengono poi richieste senza chiave.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Elimina l’ID del modello salvato. Il provider personalizzato ne ha bisogno per rispondere.",
    ["Failed"] = "Non riuscito",
    ["It answered in {ms} ms."] = "Ha risposto in {ms} ms.",
    ["It could not be saved."] = "Impossibile salvarlo.",
    ["Model ID: {model}"] = "ID modello: {model}",
    ["Only https:// works outside this computer and your home network."] = "Fuori da questo computer e dalla tua rete domestica funziona solo https://.",
    ["Paste API key"] = "Incolla chiave API",
    ["Paste endpoint URL"] = "Incolla URL endpoint",
    ["Paste model ID"] = "Incolla ID modello",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Invia un messaggio minuscolo al tuo endpoint con l’ID del modello e la chiave salvati, e mostra come ha risposto. Consuma quasi nulla dei tuoi crediti.",
    ["Test"] = "Prova",
    ["Test connection"] = "Prova connessione",
    ["Testing the connection…"] = "Prova della connessione in corso…",
    ["Testing…"] = "Prova in corso…",
    ["That is too long."] = "È troppo lungo.",
    ["That was not accepted."] = "Non è stato accettato.",
    ["The account is out of credits. Add credits with your provider."] = "Il conto non ha più crediti. Aggiungi crediti presso il tuo provider.",
    ["The address must start with https:// or http://."] = "L’indirizzo deve iniziare con https:// o http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "L’indirizzo ti porta altrove. Usa l’indirizzo finale indicato dal tuo provider.",
    ["The clipboard does not hold a model ID."] = "Negli appunti non c’è un ID del modello.",
    ["The clipboard does not hold a web address."] = "Negli appunti non c’è un indirizzo web.",
    ["The clipboard does not hold an API key."] = "Negli appunti non c’è una chiave API.",
    ["The clipboard is empty. Copy it first."] = "Gli appunti sono vuoti. Copia prima.",
    ["The connection test failed."] = "Il test di connessione è fallito.",
    ["The connection works. The endpoint accepted your model and key."] = "La connessione funziona. L’endpoint ha accettato il tuo modello e la tua chiave.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "Il servizio di conversazione non è in esecuzione, quindi non si può testare nulla. Riavvia il gioco.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Personalizzato: chiave rifiutata. Controllala in Impostazioni > Fornitore di conversazione.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Provider personalizzato senza risposta. Controlla l’indirizzo in Impostazioni o riprova.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Il provider personalizzato non riconosce l’ID. Controllalo in Impostazioni.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Provider personalizzato non configurato: si usa Convai. Aggiungi URL e ID modello in Impostazioni.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "Il provider personalizzato ti sta limitando. Riprova tra un momento.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Provider personalizzato: crediti esauriti. Aggiungi crediti lì e riprova.",
    ["The endpoint URL was removed."] = "L’URL endpoint è stato rimosso.",
    ["The endpoint answered with no text. Check the model ID."] = "L’endpoint ha risposto senza testo. Controlla l’ID del modello.",
    ["The endpoint did not accept your API key."] = "L’endpoint non ha accettato la tua chiave API.",
    ["The endpoint did not answer. Check its address."] = "L’endpoint non ha risposto. Controlla l’indirizzo.",
    ["The endpoint does not know that model ID."] = "L’endpoint non riconosce questo ID del modello.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "L’endpoint ti sta limitando. Riprova tra un momento.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "L’endpoint ti sta limitando. Attendi circa {seconds} secondi, poi riprova.",
    ["The endpoint refused the request. Check the model ID and the address."] = "L’endpoint ha rifiutato la richiesta. Controlla l’ID del modello e l’indirizzo.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "L’endpoint ha segnalato un errore dal suo lato. Riprova tra un momento.",
    ["The endpoint took too long to answer."] = "L’endpoint ha impiegato troppo tempo a rispondere.",
    ["The model ID was removed."] = "L’ID del modello è stato rimosso.",
    ["The provider said: {detail}"] = "Il provider ha detto: {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Questo indirizzo non è cifrato, il che va bene sul tuo computer o nella tua rete domestica.",
    ["Use the base URL only: no password, query or #."] = "Usa solo l’URL di base: niente password, query o #.",
    ["Waiting for the endpoint to answer…"] = "In attesa della risposta dell’endpoint…",
    ["Custom: free daily limit reached"] = "Personalizzato: limite giornaliero gratuito raggiunto",
    ["New address saved. Paste your API key again for it."] = "Nuovo indirizzo salvato. Incolla di nuovo la chiave API.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Limite giornaliero gratuito di questo modello raggiunto. Si ripristina alle {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Limite giornaliero gratuito di questo modello raggiunto. Riprova dopo il ripristino.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Il modello ragiona e non risponde. Scegli un modello senza ragionamento in Impostazioni.",
    ["All"] = "Tutti",
    ["Also changed: {names}."] = "Anche modificato: {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Scegli un personaggio qualsiasi dall'elenco qui sotto. Non deve far parte del tuo gruppo attuale.",
    ["Defaults restored."] = "Valori predefiniti ripristinati.",
    ["Drag the slider, or press left and right, to turn the page."] = "Trascina il cursore o premi le frecce sinistra e destra per cambiare pagina.",
    ["How loud the mod’s voices are, for companions, characters and V’s typed lines. 100 is the normal level.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. The game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Quanto sono alte le voci del mod, per compagni, personaggi e frasi digitate da V. 100 è il livello normale.\n\nSopra 100 le voci diventano più forti, con un limitatore per evitare distorsioni. I dialoghi e i suoni del gioco non cambiano.\n\nLa risposta successiva lo usa.",
    ["Not available right now."] = "Al momento non disponibile.",
    ["Open Settings to restore its defaults."] = "Apri Impostazioni per ripristinare i valori predefiniti.",
    ["Page"] = "Pagina",
    ["Show only the models whose name starts with this letter."] = "Mostra solo i modelli il cui nome inizia con questa lettera.",
    ["Starts with"] = "Inizia con",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Apri AI NPC Cyberpunk Mod nell’elenco dei mod.",
    ["The settings could not be saved. Nothing was changed."] = "Impossibile salvare le impostazioni. Non è stato modificato nulla.",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Mistral (with your free key, about 5,000 turns a day) or Local AI (unlimited)."] = "Hai usato i tuoi {limit} turni di oggi. Tornano domani. Per continuare subito, scegli Mistral (con la tua chiave gratuita, circa 5.000 turni al giorno) oppure Local AI (nessun limite).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Chi scrive le risposte dei tuoi compagni. Una modifica attende che nessuna conversazione sia in corso.\n\nIl piano gratuito di Convai non richiede configurazione e offre risposte migliori. La chiave API di Convai usa la tua chiave. Mistral usa il suo piano gratuito con la tua chiave gratuita; la memoria resta su questo computer.\n\nCon Mistral, Local AI o Personalizzato, la voce cloud di Convai viene sostituita da una voce locale. Il riconoscimento vocale avviene su questo computer, quindi la chiave vocale funziona.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Chi scrive le risposte dei tuoi compagni. Una modifica attende che nessuna conversazione sia in corso.\n\nIl piano gratuito di Convai non richiede configurazione e offre risposte migliori. La chiave API di Convai usa la tua chiave. Mistral usa il suo piano gratuito con la tua chiave gratuita; la memoria resta su questo computer.\n\nCon Mistral, Local AI o Personalizzato, la voce cloud di Convai viene sostituita da una voce locale. Il riconoscimento vocale per la chiave vocale non è ancora disponibile con questi, quindi scrivi i tuoi messaggi.",
    ["Privacy"] = "Privacy",
    ["Send error reports automatically"] = "Segnalazione automatica errori",
    ["When something in the mod goes wrong, a short report goes to the developer so it can be fixed without asking you for logs. At most five a day.\n\nIt holds the error, the mod and requirement versions, your provider and voice choices, whether Mature content is on, your graphics card, the setup check and the log lines around the error. If replies stay slow, it also holds how long a few recent replies took, stage by stage.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name."] = "Quando qualcosa nella mod va storto, una breve segnalazione viene inviata allo sviluppatore, così l'errore può essere corretto senza chiederti i log. Al massimo cinque al giorno. Se le risposte restano lente, contiene anche quanto hanno impiegato alcune risposte recenti, fase per fase.\n\nContiene l'errore, le versioni della mod e dei suoi requisiti, le tue scelte di provider e voce, se i Contenuti maturi sono attivi, la tua scheda grafica, il risultato del controllo di configurazione e le righe di log intorno all'errore.\n\nNon contiene mai chiavi, ciò che tu o i personaggi dite, ricordi, audio né il tuo nome utente di Windows.",
    ["Error reports go to the developer automatically. Turn them off in Settings > Privacy."] = "Errori segnalati automaticamente allo sviluppatore. Disattivali: Impostazioni > Privacy.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "Gestione compagni richiede Mod Configuration Menu 0.10.5 o successivo, oppure Native Settings UI",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "Aggiorna Mod Configuration Menu alla 0.10.5 o successiva, oppure installa Native Settings UI",
    ["Stand up to open the Companion Manager"] = "Alzati per aprire Gestione compagni",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI 1.96 or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "Gestione compagni richiede Mod Configuration Menu 0.10.5 o successivo, oppure Native Settings UI 1.96 o successivo. Basta uno dei due. Installane uno da Nexus Mods e riavvia il gioco.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer, or install Native Settings UI, then restart the game."] = "Mod Configuration Menu è troppo vecchio. Aggiornalo alla 0.10.5 o successiva, oppure installa Native Settings UI, poi riavvia il gioco.",
    ["Previous page"] = "Pagina precedente",
    ["Next page"] = "Pagina successiva",
    ["Starts with: {letter}"] = "Inizia con: {letter}",
    ["Characters and party"] = "Personaggi e gruppo",
    ["Load a save first"] = "Carica prima un salvataggio",
    ["Inviting characters and managing your party need a loaded game."] = "Invitare personaggi e gestire il gruppo richiede una partita caricata.",
    ["Voxtral (recommended)"] = "Voxtral (consigliato)",
    ["Defaults"] = "Standard",
    ["Press Confirm to put every setting back to its default."] = "Premi Conferma per riportare ogni impostazione al suo valore predefinito.",
    ["Local AI stopped working and was restarted."] = "Local AI ha smesso di funzionare ed è stata riavviata.",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "Local AI qui gira soprattutto sul tuo processore, quindi le risposte saranno lente.",
    ["TweakXL is missing. Install TweakXL from Nexus Mods (nexusmods.com/cyberpunk2077/mods/4197), extract it into the Cyberpunk 2077 folder, then restart the game."] = "TweakXL è assente. Installa TweakXL da Nexus Mods (nexusmods.com/cyberpunk2077/mods/4197), estrailo nella cartella di Cyberpunk 2077, poi riavvia il gioco.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate. The microphone uses this language as a hint for non-English speech."] = "Cambia solo i menu e gli avvisi della mod.\n\nLe voci dei personaggi e la lingua in cui parli sono separate. Il microfono usa questa lingua come indizio per il parlato in lingue diverse dall’inglese.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. Each character decides when; it stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice while Convai answers: choosing it turns this off, and turning this on switches the voice to Pocket. With Mistral, Local AI or Custom it works."] = "I compagni ogni tanto si fermano, esitano, ridono o sospirano, come farebbe la loro personalità. Ogni personaggio decide quando; resta raro.\n\nOmniVoice può far sentire risate e sospiri; le altre voci aggiungono solo pause.\n\nNon disponibile con la voce cloud di Convai mentre Convai risponde: sceglierla lo disattiva, e attivarlo passa la voce a Pocket. Con Mistral, Local AI o Personalizzato funziona.",
    ["Voxtral stops speaking; companion replies show as text until a key is saved."] = "Voxtral smette di parlare; le risposte dei compagni appaiono come testo finché non viene salvata una chiave.",
    ["Conversations go back to Convai free tier."] = "Le conversazioni tornano a Convai (piano gratuito).",
    ["Deletes the saved key."] = "Elimina la chiave salvata.",
    ["Nothing you use now depends on it."] = "Nulla di ciò che usi ora dipende da essa.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "La voce cloud di Convai non può usare la parlata naturale, quindi è stata disattivata.",
    ["Custom endpoint"] = "Endpoint personale",
    ["Johnny Silverhand answers when you use the talk keys with nobody in front of you, as the voice in V’s head. He knows your jobs and your story so far, and what he thinks of you follows it.\n\nOnly while the story has him in V’s head. He stays quiet during scenes, calls, dialogue choices and fights, and when the game gives him a line.\n\nOn: he answers when you talk to him. Speaks up rarely: he also says something on his own, at most twice an hour. Speaks up often: at most six times an hour, never closer than five minutes. He speaks up after you meet someone he knows of, finish a job, a romance moves on, you arrive somewhere he knows, the Relic acts up, or a big fight ends.\n\nOn the Convai free tier each remark uses one of the day’s turns; remarks never take more than a tenth of them."] = "Johnny Silverhand ti risponde quando usi i tasti per parlare senza nessuno davanti, come la voce nella testa di V. Conosce i tuoi lavori e la tua storia finora, e ciò che pensa di te segue di conseguenza.\n\nSolo mentre la storia lo tiene nella testa di V. Resta in silenzio durante scene, chiamate, scelte di dialogo e combattimenti, e quando il gioco gli assegna una battuta.\n\nAttivato: ti risponde quando gli parli. Interviene raramente: dice anche qualcosa di sua iniziativa, al massimo due volte all’ora. Interviene spesso: al massimo sei volte all’ora, mai a meno di cinque minuti di distanza. Interviene dopo che incontri qualcuno di cui ha sentito parlare, completi un incarico, una storia d’amore va avanti, arrivi in un posto che conosce, la Relic fa i capricci o finisce un grosso scontro.\n\nCon il piano gratuito di Convai, ogni commento usa uno dei turni di oggi; i commenti non occupano mai più di un decimo di essi.",
    ["Speaks up often"] = "Interviene spesso",
    ["Speaks up rarely"] = "Interviene raramente",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "L’indirizzo, la chiave API e l’ID del modello del tuo fornitore compatibile con OpenAI, e un test di connessione. Usato quando Personalizzato è il Fornitore di conversazione.",
    ["V’s voice switches from Voxtral to Pocket."] = "La voce di V passa da Voxtral a Pocket.",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · manca pacchetto",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · serve voce Omni",
    ["OmniVoice · short wait"] = "OmniVoice · breve attesa",
    ["Requires the Companion voices to be an OmniVoice choice"] = "Richiede che le voci dei compagni siano la scelta OmniVoice",
    ["V’s voice switches from OmniVoice to Pocket."] = "La voce di V passa da OmniVoice a Pocket.",
    ["When you type a line, V says it out loud too, in the male or female V voice that matches yours. Push-to-talk is never replayed.\n\nV speaks first, then the companion answers. Pocket and Voxtral lines that are not ready in time are skipped; an OmniVoice line is waited for. The line always shows as a subtitle.\n\nPocket: runs on your processor and starts in about 0.2 s. If the companions use another voice, it loads its own small voice model just for V.\n\nVoxtral: made in the cloud with your Mistral key, so nothing loads on your PC. Starts in about a second, in English and many other languages.\n\nOmniVoice: uses the same GPU voice as your companions (only while they use OmniVoice); no extra model loads. It adds a short wait before replies to typed lines (about a second more than Pocket, before V starts), because V speaks first and the companion answers after."] = "Quando scrivi una riga, anche V la dice ad alta voce, con la voce maschile o femminile di V che corrisponde alla tua. Il push-to-talk non viene mai riprodotto.\n\nV parla per primo, poi risponde il compagno. Le battute di Pocket e Voxtral non pronte in tempo vengono saltate; per una battuta OmniVoice si attende. La battuta appare sempre come sottotitolo.\n\nPocket: gira sul processore e inizia in circa 0,2 s. Se i compagni usano un'altra voce, carica un proprio piccolo modello vocale solo per V.\n\nVoxtral: generato nel cloud con la tua chiave Mistral, quindi non viene caricato nulla sul PC. Inizia in circa un secondo, in inglese e in molte altre lingue.\n\nOmniVoice: usa la stessa voce GPU dei tuoi compagni (solo mentre loro usano OmniVoice); non carica modelli extra. Aggiunge una breve attesa prima delle risposte alle righe scritte (circa un secondo in più rispetto a Pocket, prima che V inizi), perché V parla per primo e il compagno risponde dopo.",
    ["V’s voice"] = "Voce di V",
    ["V (male voice)"] = "V (voce maschile)",
    ["V (female voice)"] = "V (voce femminile)",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "Usata per le battute scritte di V: Pocket, OmniVoice e la voce cloud Voxtral la copiano.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "V parla con la voce della tua mod vocale di V installata, o con la voce originale di V.",
    ["Remove the voice clip? V goes back to the voice of your installed V voice mod, or the shipped V voice."] = "Rimuovere il clip vocale? V torna alla voce della tua mod vocale di V installata o alla voce originale di V.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "OmniVoice richiede una scheda grafica NVIDIA, e questo PC non ne ha una funzionante. Le risposte appaiono come testo. Scegli Pocket in Impostazioni per sentire le voci.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "OmniVoice richiede una scheda grafica NVIDIA, e questo PC non ne ha una funzionante. I compagni usano invece {voice}.",
    ["OmniVoice needs NVIDIA"] = "OmniVoice richiede NVIDIA",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "Questo PC non ha una scheda grafica NVIDIA, necessaria a OmniVoice. OmniVoice qui non si avvia. Scegli Pocket per sentire le voci.",
    ["{voice} · needs NVIDIA card"] = "{voice} · richiede scheda NVIDIA",
}
